"use client";

import React, { useState } from 'react';
import {
    History as HistoryIcon,
    Search,
    Filter,
    Download,
    ChevronLeft,
    ChevronRight,
    User,
    Scissors,
    Calendar,
    DollarSign,
    MoreVertical
} from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';

// Mock History Data
const historyData = [
    { id: 1, date: '08/09/2026', client: 'Marcos Braz', service: 'Corte Degradê', price: 'R$ 55,00', commission: 'R$ 22,00', payment: 'PIX' },
    { id: 2, date: '08/09/2026', client: 'Lucas Silva', service: 'Degradê + Barba', price: 'R$ 85,00', commission: 'R$ 34,00', payment: 'Cartão' },
    { id: 3, date: '07/09/2026', client: 'Ricardo Alves', service: 'Barba Completa', price: 'R$ 40,00', commission: 'R$ 16,00', payment: 'Dinheiro' },
    { id: 4, date: '07/09/2026', client: 'André Santos', service: 'Corte Social', price: 'R$ 45,00', commission: 'R$ 18,00', payment: 'PIX' },
    { id: 5, date: '06/09/2026', client: 'Felipe Melo', service: 'Degradê + Pigmento', price: 'R$ 75,00', commission: 'R$ 30,00', payment: 'Cartão' },
];

export default function BarberHistory() {
    const [searchTerm, setSearchTerm] = useState('');

    return (
        <div className="max-w-6xl mx-auto space-y-10 animate-fade-in-up">
            <header className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-white/5">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight mb-1">Meu <span className="text-[var(--color-primary-gold)]">Histórico</span></h1>
                    <p className="text-gray-500 text-sm italic">O registro de todos os seus atendimentos realizados.</p>
                </div>
                <div className="flex items-center gap-3">
                    <Button variant="outline" className="h-12 px-6 rounded-xl border-white/5 uppercase text-[10px] font-black tracking-widest gap-2">
                        <Download className="w-4 h-4" /> EXPORTAR PDF
                    </Button>
                </div>
            </header>

            <div className="bg-[var(--color-dark-card)] border border-[var(--color-dark-border)] rounded-[3rem] p-8 md:p-12 shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-[var(--color-primary-gold)]/5 rounded-full blur-[100px] -mr-32 -mt-32" />

                {/* Search & Filters */}
                <div className="flex flex-col md:flex-row justify-between gap-4 mb-10 relative z-10">
                    <div className="relative w-full max-w-sm">
                        <Search className="absolute left-5 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
                        <Input
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            placeholder="Buscar cliente ou serviço..."
                            className="bg-black/40 h-14 pl-12 border-white/5 rounded-2xl"
                        />
                    </div>
                    <div className="flex items-center gap-3">
                        <Button variant="outline" className="h-14 px-6 border-white/5 rounded-2xl uppercase tracking-widest font-black text-[10px] gap-2">
                            <Calendar className="w-4 h-4" /> DATA
                        </Button>
                        <Button variant="outline" className="h-14 px-6 border-white/5 rounded-2xl uppercase tracking-widest font-black text-[10px] gap-2">
                            <Filter className="w-4 h-4" /> FILTROS
                        </Button>
                    </div>
                </div>

                {/* Grid View for Mobile / Table for Desktop */}
                <div className="overflow-x-auto relative z-10">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="border-b border-white/5">
                                <th className="py-6 text-[10px] uppercase font-black tracking-[0.2em] text-gray-600">Cliente</th>
                                <th className="py-6 text-[10px] uppercase font-black tracking-[0.2em] text-gray-600">Serviço</th>
                                <th className="py-6 text-[10px] uppercase font-black tracking-[0.2em] text-gray-600 text-center">Data</th>
                                <th className="py-6 text-[10px] uppercase font-black tracking-[0.2em] text-gray-600 text-right">Valor</th>
                                <th className="py-6 text-[10px] uppercase font-black tracking-[0.2em] text-gray-600 text-right">Comissão</th>
                                <th className="py-6 text-[10px] uppercase font-black tracking-[0.2em] text-gray-600 text-right">Ação</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/5">
                            {historyData.map((item) => (
                                <tr key={item.id} className="group hover:bg-white/[0.01] transition-all">
                                    <td className="py-8">
                                        <div className="flex items-center gap-4">
                                            <div className="w-10 h-10 rounded-xl bg-white/5 flex items-center justify-center text-gray-600 group-hover:bg-[var(--color-primary-gold)]/10 group-hover:text-[var(--color-primary-gold)] transition-colors">
                                                <User size={18} />
                                            </div>
                                            <span className="font-bold text-white tracking-tight">{item.client}</span>
                                        </div>
                                    </td>
                                    <td className="py-8">
                                        <span className="text-gray-400 font-medium italic">{item.service}</span>
                                    </td>
                                    <td className="py-8 text-center text-sm font-bold text-gray-600">{item.date}</td>
                                    <td className="py-8 text-right font-black text-white">{item.price}</td>
                                    <td className="py-8 text-right font-black text-emerald-400">{item.commission}</td>
                                    <td className="py-8 text-right">
                                        <button className="p-2 text-gray-700 hover:text-white transition-colors">
                                            <MoreVertical size={18} />
                                        </button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>

                {/* Mobile Note */}
                <p className="lg:hidden text-center text-[10px] text-gray-700 font-bold uppercase tracking-widest mt-8 italic">Arraste para o lado para ver mais detalhes</p>

                {/* Pagination */}
                <div className="mt-12 flex flex-col md:flex-row items-center justify-between gap-6 pt-10 border-t border-white/5">
                    <p className="text-xs text-gray-600 italic">Exibindo 5 de 142 atendimentos realizados.</p>
                    <div className="flex items-center gap-2">
                        <button className="p-3 bg-black border border-white/5 rounded-xl text-gray-600 hover:text-white transition-all"><ChevronLeft size={20} /></button>
                        {[1, 2, 3].map(i => (
                            <button key={i} className={`w-11 h-11 rounded-xl text-xs font-black border-2 transition-all ${i === 1 ? 'bg-[var(--color-primary-gold)] border-[var(--color-primary-gold)] text-black' : 'bg-black border-white/5 text-gray-600'}`}>{i}</button>
                        ))}
                        <button className="p-3 bg-black border border-white/5 rounded-xl text-gray-600 hover:text-white transition-all"><ChevronRight size={20} /></button>
                    </div>
                </div>
            </div>
        </div>
    );
}
